const STANCE={top_pick:['лучший выбор','#0a7d62'],recommended:['рекомендует','#0a7d62'],listed:['просто упоминает','#7b8a97'],caution:['с оговорками','#c98a1b'],negative:['не советует','#c2413a']};
/* Провал из любой цифры в список вопросов: k — что ищем, e — движок, t — тон, c — компания */
