const TABS=[['overview','Обзор'],['todo','Что делать'],['prompts','Промпты'],['cuts','Темы вопросов'],['rivals','Конкуренты'],['sources','Источники'],['fanout','Запросы ИИ'],['brand','Оценка бренда'],['method','Как считаем']];
const TOPIC=C.topics||{};
