const DIMS={tp:['Тема',TOPIC,p=>p.tp],fm:['Вид запроса',FORM,p=>p.fm],st:['Этап покупателя',STAGE,p=>(p.tags||[])[0]],lang:['Язык',{ru:'На русском',en:'На английском'},p=>p.lang]};
const ICO=window.AV_ICO||{},SHORT={ai_mode:'AI Mode',ai_overview:'Overviews'};
const OWN={own:['наш сайт','own'],sat:['наш другой сайт','sat'],satellite:['наш другой сайт','sat'],pub:['наша публикация','pub'],link:['ссылочная статья','lnk']};
const MODEL=C.models||{};
const CRIT=C.criteria||{};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const OE=esc(OUR),HL=new RegExp([C.site,OUR].filter(Boolean).map(x=>esc(x).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')||'(?!)','gi');
const f1=v=>v==null?'—':(+v).toFixed(1).replace('.',',');
const IDX=(window.AV_INDEX||{runs:[]}).runs;
const S={run:IDX.length?IDX[IDX.length-1].run:null,tab:'overview',metric:'mentions',lb:'all',lbAll:false,icp:((C.scenarios||[])[0]||[''])[0],mode:'web'};
const LOADED={};
function load(src){return new Promise(ok=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=ok;document.head.appendChild(s)})}
const sum=()=>IDX.find(r=>r.run===S.run),run=()=>(window.AV_RUN||{})[S.run],chans=()=>Object.keys(sum().engines).filter(c=>ENG[c]);
const ring=c=>`<span class="ico" style="background-image:url(${ICO[c]||''});box-shadow:0 0 0 2px ${ENG[c][1]}"></span>`;
