  `<tr><td>Ответов получено<div class="sub">в скобках — движок не показал ИИ-ответ</div></td>${cs.map(c=>`<td class="r">${s.engines[c].answers}${s.engines[c].no_answer?` (${s.engines[c].no_answer})`:''}</td>`).join('')}</tr></tbody></table></div></div>`;
