function trend(){const W=1100,H=280,L=44,R=18,T=12,B=30,k=S.metric,hid=S.hid||(S.hid={}),box=$('#trend');
 const dates=IDX.map(r=>r.run),all=Object.keys(ENG),on=all.filter(c=>!hid[c]);
 const val=(c,i)=>(IDX[i].engines[c]||{})[k];
 let max=5;on.forEach(c=>dates.forEach((_,i)=>{const v=val(c,i);if(v!=null)max=Math.max(max,v)}));max=Math.ceil(max/5)*5;
 const x=i=>L+(dates.length<2?(W-L-R)/2:i*(W-L-R)/(dates.length-1)),y=v=>T+(H-T-B)*(1-v/max),step=dates.length>1?(W-L-R)/(dates.length-1):W-L-R;
 let o=`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Динамика по замерам" style="display:block">`;
 for(let i=0;i<=5;i++){const g=max*i/5;o+=`<line x1="${L}" x2="${W-R}" y1="${y(g)}" y2="${y(g)}" stroke="var(--line)"/><text x="${L-8}" y="${y(g)+4}" text-anchor="end">${g}%</text>`}
 dates.forEach((d,i)=>{if(dates.length<14||i%2===0||i===dates.length-1)o+=`<text x="${x(i)}" y="${H-8}" text-anchor="middle">${day(d)}</text>`});
 on.forEach(c=>{const col=ENG[c][1],mine=[];dates.forEach((_,i)=>{const v=val(c,i);if(v!=null)mine.push([x(i),y(v)])});
  if(mine.length>1)o+=`<polyline points="${mine.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${col}" stroke-width="2.6"/>`;
  mine.forEach(p=>{o+=`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="${col}" stroke="var(--card)" stroke-width="2"/>`});
  const lp=mine[mine.length-1];if(lp)o+=`<circle cx="${lp[0]}" cy="${lp[1]}" r="10" fill="#fff" stroke="${col}" stroke-width="2"/><image href="${ICO[c]||''}" x="${lp[0]-7}" y="${lp[1]-7}" width="14" height="14"/>`});
 o+=`<line id="hvl" y1="${T}" y2="${H-B}" stroke="var(--ink)" stroke-width="1" opacity="0"/>`+dates.map((d,i)=>`<rect class="hv" data-i="${i}" x="${x(i)-step/2}" y="${T}" width="${step}" height="${H-T-B}" fill="transparent"/>`).join('')+'</svg>';
 box.innerHTML=o+'<div class="tip" id="tip"></div><div class="legend">'+all.map(c=>`<button class="lg ${hid[c]?'off':''}" data-c="${c}">${ring(c)}${ENG[c][0]}</button>`).join('')+`<button class="lg" data-c="*">${on.length===all.length?'Скрыть все':'Показать все'}</button></div>`;
 const tip=$('#tip'),line=box.querySelector('#hvl');
 box.querySelectorAll('rect.hv').forEach(r=>{r.onmouseenter=()=>{const i=+r.dataset.i,rows=on.map(c=>[c,val(c,i)]).filter(v=>v[1]!=null).sort((a,b)=>b[1]-a[1]);
   line.setAttribute('x1',x(i));line.setAttribute('x2',x(i));line.setAttribute('opacity',.35);
   tip.innerHTML=`<b>${day(dates[i])}.${dates[i].slice(0,4)}</b>`+(rows.map(([c,v])=>`<div>${ring(c)}${ENG[c][0]}<b>${f1(v)}%</b></div>`).join('')||'<div class="sub">нет данных</div>');
   const pc=100*x(i)/W;tip.style.left=pc+'%';tip.style.transform=pc>62?'translateX(calc(-100% - 14px))':'translateX(14px)';tip.style.display='block'}});
 box.querySelector('svg').onmouseleave=()=>{tip.style.display='none';line.setAttribute('opacity',0)};
 box.querySelectorAll('.lg').forEach(b=>b.onclick=()=>{const c=b.dataset.c;if(c==='*'){const hideAll=on.length===all.length;all.forEach(e=>hid[e]=hideAll)}else hid[c]=!hid[c];trend()})}

/* ---------- Промпты ---------- */
async function prompts(){const d=run();if(!d)return;const cs=chans(),P=S.p||(S.p={q:'',k:'',e:'',t:'',l:'',c:'',g:'',s:null}),el=$('#t-prompts'),pd=prevRun(),s0=sum();
 if(P.s&&!d.refs&&s0.ref_parts){el.innerHTML='<div class="card"><p class="hint">Загружаю…</p></div>';await Promise.all(Array.from({length:s0.ref_parts},(_,i)=>load(`data/${S.run}_refs_${i}.js`)));if(S.tab!=='prompts'||S.p!==P)return}
 let SR=null;if(P.s){SR=new Set();const CH=s0.channels||[];(((d.refs||{})[P.s.k])||'').split(' ').forEach(t=>{const m=/^(\d+)([a-z])$/.exec(t);if(m&&d.prompts[+m[1]])SR.add(d.prompts[+m[1]].id+'|'+CH[m[2].charCodeAt(0)-97])})}
 const pm={};if(pd)pd.prompts.forEach(p=>pm[p.id]=p);const pv=(p,c)=>{const y=pm[p.id]&&pm[p.id].cells[c];return y&&y.s==='ok'?y:null},our=x=>x.c||x.n||x.u||x.l;
 const KINDS=[['','Любые ответы'],['m',OE+' назван'],['nm',OE+' не назван'],['c','Процитирован любой наш источник'],['c4','Процитирован '+esc(C.site||'')],['cn','Процитирован другой наш сайт'],['cu','Процитирована наша публикация'],['cl','Процитирована ссылочная статья'],['g','Наш источник процитирован, но '+OE+' не назван'],['f','Нашу страницу нашли, но не процитировали'],['r','Названы только другие компании'],['z','Компаний нет'],
  ...(pd?[['up','К прошлому замеру: '+OE+' появился'],['dn','К прошлому замеру: '+OE+' пропал'],['cup','К прошлому замеру: наш источник появился'],['cdn','К прошлому замеру: наш источник пропал']]:[])].filter(x=>KON(x[0]));
 const TONES=[['','Любой тон'],['pos','Лучший выбор или рекомендует'],...Object.keys(STANCE).map(k=>[k,STANCE[k][0][0].toUpperCase()+STANCE[k][0].slice(1)])];
 const opt=(l,v)=>l.map(o=>`<option value="${o[0]}" ${o[0]===v?'selected':''}>${o[1]}</option>`).join('');
 const gopt=`<option value="">Все темы и виды вопросов</option>`+Object.entries(DIMS).filter(([k])=>k!=='lang').map(([k,v])=>`<optgroup label="${v[0]}">${opt(Object.entries(v[1]).map(([a,b])=>[k+':'+a,b]),P.g)}</optgroup>`).join('');
 el.innerHTML=`<div class="card"><h2>Вопросы покупателей и ответы движков</h2><p class="hint">Каждый вопрос задаётся каждому движку отдельно, в чистом диалоге. Нажмите на ячейку, чтобы прочитать ответ, источники и поисковые запросы движка. Фильтры сочетаются: например, «Claude» и «с оговорками» покажут вопросы, где Claude назвал нас с оговоркой.</p>
 <div class="filters"><input type="search" id="q" placeholder="Поиск по тексту вопроса" size="26" value="${esc(P.q)}"><select id="pk">${opt(KINDS,P.k)}</select><select id="pe">${opt([['','Все движки'],...cs.map(c=>[c,ENG[c][0]])],P.e)}</select><select id="pt">${opt(TONES,P.t)}</select><select id="pg">${gopt}</select><select id="lf">${opt([['','Все языки'],['ru','Русские'],['en','Английские']],P.l)}</select>${P.c?`<span class="pill us" style="margin:0">Компания: ${esc(P.c)}</span>`:''}${P.s?`<span class="pill sat" style="margin:0" title="Показаны ответы, где этот источник процитирован">Источник: ${esc(P.s.n)}</span>`:''}<button class="x" id="preset" style="float:none">Сбросить</button><span class="sub" id="pcount"></span></div>
 <div class="scroll"><table id="pt2"></table></div>
 <div class="legend"><span><i class="sw" style="background:${STANCE.recommended[1]}"></i>советует ${OE} (★ — лучший выбор)</span><span><i class="sw" style="background:${STANCE.listed[1]}"></i>просто упоминает</span><span><i class="sw" style="background:${STANCE.caution[1]}"></i>с оговорками</span><span>цифра — место ${OE} среди компаний в ответе</span><span><i class="sw" style="box-shadow:inset 0 0 0 2px var(--link)"></i>процитирован ${esc(C.site||'')}</span><span>с — другой наш сайт, п — наша публикация, л — ссылочная статья</span><span>– движок не дал ИИ-ответ</span>${pd?'<span><b style="color:var(--us)">▲</b> '+OE+' появился к прошлому замеру, <b style="color:var(--red)">▼</b> пропал</span>':''}</div></div>`;
 const co=x=>(x.a&&x.a.length?x.a:x.b)||[];
 const KIND={m:x=>x.m,nm:x=>!x.m,c:our,c4:x=>x.c,cn:x=>x.n,cu:x=>x.u,cl:x=>x.l,g:x=>our(x)&&!x.m,f:x=>x.f&&!x.n&&!x.c,
  up:(x,p,c)=>{const y=pv(p,c);return x.m&&y&&!y.m},dn:(x,p,c)=>{const y=pv(p,c);return !x.m&&y&&y.m},cup:(x,p,c)=>{const y=pv(p,c);return our(x)&&y&&!our(y)},cdn:(x,p,c)=>{const y=pv(p,c);return !our(x)&&y&&our(y)}};
 const tone=x=>!P.t||(x.m&&(P.t==='pos'?(x.t==='top_pick'||x.t==='recommended'):(x.t||'listed')===P.t)),comp=x=>!P.c||co(x).includes(P.c);
 const hit=(x,p,c)=>x&&x.s==='ok'&&(!KIND[P.k]||KIND[P.k](x,p,c))&&tone(x)&&comp(x)&&(!SR||SR.has(p.id+'|'+c)),narrow=()=>KIND[P.k]||P.t||P.c||SR;
 const gm=p=>{if(!P.g)return true;const i=P.g.indexOf(':'),D=DIMS[P.g.slice(0,i)];return !!D&&D[2](p)===P.g.slice(i+1)};
 const match=p=>{if(P.q&&!p.text.toLowerCase().includes(P.q.toLowerCase()))return false;if(P.l&&p.lang!==P.l)return false;if(!gm(p))return false;
  const ch=P.e?[P.e]:cs,cells=ch.map(c=>p.cells[c]).filter(x=>x&&x.s==='ok');
  if(P.k==='r')return !cells.some(x=>x.m)&&cells.some(x=>co(x).length&&comp(x));if(P.k==='z')return cells.length>0&&!cells.some(x=>co(x).length);
  if(!narrow()&&!P.e)return true;return ch.some(c=>hit(p.cells[c],p,c))};
 const draw=()=>{const rows=d.prompts.filter(match);let answers=0;
  $('#pt2').innerHTML=`<thead><tr><th style="min-width:300px">Вопрос</th><th class="c">Назван</th>${cs.map(c=>`<th class="c" style="white-space:nowrap">${dot(c)}${ENG[c][0].replace('Google ','')}</th>`).join('')}<th style="min-width:230px">Кого называют чаще</th></tr></thead><tbody>`+rows.map(p=>{
   const nm=cs.filter(c=>p.cells[c]&&p.cells[c].m).length,br={};cs.forEach(c=>co(p.cells[c]||{}).forEach(b=>br[b]=(br[b]||0)+1));
   return `<tr><td>${esc(p.text)}${TOPIC[p.tp]?`<div class="sub" style="font-size:12.5px">${TOPIC[p.tp]}</div>`:''}</td><td class="c" style="white-space:nowrap">${nm?`<b>${nm}</b>`:'0'} из ${cs.length}</td>`+cs.map(c=>{const x=p.cells[c];
    if(!x)return '<td class="c"><span class="cell na">·</span></td>';
    if(x.s!=='ok')return `<td class="c"><button class="cell" data-p="${p.id}" data-c="${c}" title="${x.s==='no_answer'?'ИИ-ответа не было':'ошибка съёма'}">${x.s==='no_answer'?'–':'!'}</button></td>`;
    const st=x.m?(STANCE[x.t]||STANCE.listed):null,h=(!P.e||P.e===c)&&hit(x,p,c),dim=(narrow()||P.e)&&!h,y=pv(p,c),ch=y?(x.m&&!y.m?'gain':!x.m&&y.m?'loss':''):'';if(h&&(narrow()||P.e))answers++;
    return `<td class="c"><button class="cell ${x.c?'cited':''} ${dim?'dim':''} ${ch}" data-p="${p.id}" data-c="${c}" ${st?`style="background:${st[1]};color:#fff" title="${st[0]}, место ${x.pos||'—'}${ch?', в прошлом замере ${OE} не был назван':''}"`:`title="${OE} не назван${x.n?', процитирован другой наш сайт':x.u?', процитирована наша публикация':x.l?', процитирована ссылочная статья':''}${ch?', в прошлом замере был назван':''}"`}>${x.m?(x.t==='top_pick'?'★':'')+(x.pos?'#'+x.pos:'✓'):(x.c?'':x.n?'с':x.u?'п':x.l?'л':'')}</button></td>`}).join('')+
   `<td class="sub">${Object.entries(br).sort((a,b)=>b[1]-a[1]).slice(0,5).map(b=>b[0]===OUR?'<b>'+OE+'</b>':esc(b[0])).join(', ')||'—'}</td></tr>`}).join('')+'</tbody>';
  $('#pcount').textContent=`${rows.length} из ${d.prompts.length} вопросов`+(answers?`, подходящих ответов: ${answers}`:'');
  $$('#pt2 .cell[data-p]').forEach(e=>e.onclick=()=>answer(e.dataset.p,e.dataset.c))};
 $('#q').oninput=e=>{P.q=e.target.value;draw()};[['#pk','k'],['#pe','e'],['#pt','t'],['#pg','g'],['#lf','l']].forEach(([id,key])=>$(id).onchange=e=>{P[key]=e.target.value;draw()});
 $('#preset').onclick=()=>{S.p=null;prompts()};draw()}

async function answer(pid,ch){const key=S.run+'/'+ch,d=run();
 if(!LOADED[key]){const n=((d.parts||{})[ch])||0;await Promise.all(Array.from({length:n},(_,i)=>load(`data/${S.run}_${ch}_${i}.js`)));LOADED[key]=1}
 const a=((window.AV_ANS||{})[key]||{})[pid],p=d.prompts.find(x=>x.id===pid),cs=chans();if(!a)return;
 let t=(a.text||'').replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/\[([^\]]*)\]\((https?:[^)\s]*)\)/g,'$1').replace(/\\([.\-:()#*])/g,'$1').replace(/^\s*(---+|Официальный сайт|Official site)\s*$/gmi,'').replace(/\n{3,}/g,'\n\n');
 t=esc(t).replace(/^#{1,6}\s*(.+)$/gm,'<b>$1</b>').replace(/\*\*([^*\n]+)\*\*/g,'<b>$1</b>').replace(HL,m=>`<mark>${m}</mark>`);
  const st=a.stance?STANCE[a.stance]:null,comp=a.companies&&a.companies.length?a.companies:(a.brands||[]).map(b=>({name:b,rec:true}));
 $('#dh').innerHTML=`<button class="x" id="dx">Закрыть</button><h2 style="padding-right:96px">${esc(p.text)}</h2><div style="margin-top:10px">${seg('aseg',cs.map(c=>[c,ENG[c][0]]),ch)}</div>`;
 $('#db').innerHTML=`<dl class="kv"><dt>Модель</dt><dd>${esc(a.model||'—')}</dd><dt>Когда спрошено</dt><dd>${esc((a.asked_at||'').slice(0,16))||'—'}</dd><dt>${OE}</dt><dd>${st?`<span class="pill" style="background:${st[1]};color:#fff">${st[0]}</span> ${esc(a.why||'')}`:(a.status==='ok'?'не назван':a.status==='no_answer'?'движок не дал ИИ-ответ':'ошибка: '+esc(a.error||''))}</dd></dl>
 ${a.quote?`<blockquote>${esc(a.quote)}</blockquote>`:''}
 <h3 style="margin-top:22px">Компании в ответе, по порядку</h3><div>${comp.length?comp.map((c,i)=>`<span class="pill ${c.name===OUR?'us':''} ${c.rec===false?'off':''}" title="${c.rec===false?'упомянута как неподходящая или недоступная':'предложена как вариант'}">${i+1}. ${esc(c.name)}</span>`).join(''):'<span class="sub">ни одной</span>'}</div>
 ${comp.some(c=>c.rec===false)?'<div class="sub">Зачёркнуты компании, которые движок назвал как неподходящие или недоступные.</div>':''}
 <h3 style="margin-top:22px">Ответ</h3><pre>${t||'<span class="sub">Текста нет.</span>'}</pre>
 <h3 style="margin-top:22px">Источники в ответе: ${a.sources.length}</h3>${a.sources.length?'<ol style="margin:0;padding-left:20px">'+a.sources.map(s=>`<li>${OWN[s.o]?`<span class="pill ${OWN[s.o][1]}">${OWN[s.o][0]}</span>`:''}${esc(s.domain)} — <a href="${esc(s.url)}" target="_blank" rel="noopener">${esc((s.title||s.url).slice(0,90))}</a>${s.x?`<div class="sub">К этой фразе ответа привязана ссылка: «${esc(s.x)}»</div>`:''}${s.xs?`<div class="sub">Фрагмент страницы, который показал движок: «${esc(s.xs)}»</div>`:''}</li>`).join('')+'</ol>':'<span class="sub">движок не показал источников</span>'}
 <h3 style="margin-top:22px">Что движок искал: ${a.fanout.length}</h3>${a.fanout.length?'<ol style="margin:0;padding-left:20px">'+a.fanout.map(q=>`<li>${esc(q)}</li>`).join('')+'</ol>':'<span class="sub">этот движок не отдаёт подзапросы, либо поиска не было</span>'}
 <h3 style="margin-top:22px">Что вернул поиск движка: ${a.found.length} сайтов</h3><div class="sub" style="margin-bottom:6px">Это результаты поиска, которые движок получил перед ответом. Сослался он только на те, что в списке источников выше; читал ли остальные, мы не знаем.</div><div class="sub">${a.found.map(x=>(a.found_ours||[]).includes(x)?'<mark>'+esc(x)+'</mark>':esc(x)).join(', ')||'—'}</div>`;
 $('#drawer').classList.add('on');$('#shade').classList.add('on');$('#db').scrollTop=0;$('#dx').onclick=closeDrawer;onSeg('aseg',v=>answer(pid,v))}
